import { useState } from 'react'
import { ChevronDown, CircleSlash2, Rows3, Table2 } from 'lucide-react'
import { ExecutionLedger } from '../components/ExecutionLedger'
import type { EventAggregate } from '../domain/types'
import { useApp } from '../state/AppContext'
import { dateTime, money, number, percent, signedMoney } from '../utils/format'

const EventDetails = ({ event }: { event: EventAggregate }) => {
  const { analysis } = useApp()
  const [mode, setMode] = useState<'compact' | 'extensive'>('compact')
  const positions = analysis?.compactPositions.filter(position => position.eventTicker === event.eventTicker) ?? []
  const trades = analysis?.trades.filter(trade => trade.eventTicker === event.eventTicker) ?? []
  return (
    <div className='event-details'>
      <div className='event-details__toolbar'>
        <div className='segmented' aria-label='Modo do histórico'>
          <button type='button' className={mode === 'compact' ? 'active' : ''} onClick={() => setMode('compact')}><Table2 size={15} aria-hidden='true' />Compacto</button>
          <button type='button' className={mode === 'extensive' ? 'active' : ''} onClick={() => setMode('extensive')}><Rows3 size={15} aria-hidden='true' />Extenso</button>
        </div>
      </div>
      {mode === 'compact' ? (
        <div className='table-scroll'>
          <table>
            <thead><tr><th>Mercado / lado</th><th>Volume</th><th>VWAP</th><th>Custo</th><th>Taxas</th><th>Payout</th><th>PnL</th><th>ROI</th><th>Janela</th></tr></thead>
            <tbody>{positions.map(position => <tr key={position.key}><th><code>{position.marketTicker}</code><span className={`tag tag--${position.direction.toLocaleLowerCase()}`}>{position.outcome || position.direction}</span></th><td>{money(position.volume)}</td><td>{number(position.averagePrice, 2)}¢</td><td>{money(position.totalCost)}</td><td>{money(position.fees)}</td><td>{position.settledTrades ? money(position.payout) : '—'}</td><td className={position.settledTrades ? position.pnl >= 0 ? 'positive' : 'negative' : ''}>{position.settledTrades ? signedMoney(position.pnl) : 'Pendente'}</td><td>{percent(position.roi)}</td><td><span>{dateTime(position.firstTrade)}</span><span>{dateTime(position.lastTrade)}</span></td></tr>)}</tbody>
          </table>
        </div>
      ) : <ExecutionLedger trades={trades} ariaLabel={`Execuções de ${event.eventTicker}`} showEventName={false} />}
    </div>
  )
}

const HistoryEvent = ({ event }: { event: EventAggregate }) => {
  const { friendlyNames, metadata } = useApp()
  const name = friendlyNames[event.eventTicker] ?? event.eventTicker
  const official = metadata[event.eventTicker]?.title ?? name
  const source = event.activities.some(activity => activity.source === 'polymarket') ? 'polymarket' : 'kalshi'
  return (
    <details className='event-accordion'>
      <summary>
        <div className='event-summary__identity'><h3 title={official}>{name}</h3><div><code title={event.eventTicker}>{event.eventTicker.replace(/^POLY:/, '')}</code><span className={`tag tag--${source === 'polymarket' ? 'polymarket' : 'source'}`}>{source.toUpperCase()}</span><span>{event.seriesTicker}</span></div></div>
        <div className='event-summary__stats'><span>{event.marketCount} mercados</span><span>{event.trades} fills</span><span>{money(event.volume)} volume</span></div>
        {event.settledTrades ? <strong className={event.pnl >= 0 ? 'positive' : 'negative'}>{signedMoney(event.pnl)}</strong> : <strong className='pending'>Resultado pendente</strong>}
        <time>{dateTime(event.lastTrade)}</time>
        <ChevronDown className='event-chevron' aria-hidden='true' />
      </summary>
      <EventDetails event={event} />
    </details>
  )
}

export const History = () => {
  const { analysis } = useApp()
  const events = analysis?.events ?? []
  return (
    <div className='view-stack view-enter'>
      <section className='history-heading'>
        <div><span className='eyebrow'>LEDGER NAVEGÁVEL</span><h2>Histórico por evento</h2><p>Eventos ordenados pela transação mais recente. Abra um item para alternar entre síntese econômica e execuções individuais.</p></div>
        <span className='history-count'>{number(events.length)} eventos</span>
      </section>
      <div className='event-list'>
        {events.map(event => <HistoryEvent event={event} key={event.eventTicker} />)}
        {!events.length && <div className='empty-state'><CircleSlash2 aria-hidden='true' /><h3>Nenhum evento neste recorte</h3><p>Remova filtros, atualize suas contas ou importe outro snapshot.</p></div>}
      </div>
    </div>
  )
}
